    let player_position = WorldPosition::new(0, 0.0, 0.0, 0.0, 0.0);
    let mut player = test_player_runtime(7, SessionId::next(), player_position);
    player.class = 4;
    player.power4 = POWER_ENERGY_DEFAULT;
